        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        assert(!collectReverted && afterBalance == beforeBalance - collectAmount && cBalanceAfter == cBalanceBefore - collectAmount);
    }
}
